class Solution {
  private static int dist(int a, int b) {
    int d = Math.abs(a - b);
    return Math.min(d, 10 - d);
  }

  public int minRotations(int n, String s) {
    int[] d = new int[n];
    for (int i = 0; i < n; i++) d[i] = s.charAt(i) - '0';
    long[] prefix = new long[n + 1];
    int pointer = 0;
    for (int i = 0; i < n; i++) {
      prefix[i + 1] = prefix[i] + dist(pointer, d[i]);
      pointer = d[i];
    }
    long[] suffixAdj = new long[n + 1];
    for (int i = n - 2; i >= 0; i--) suffixAdj[i] = suffixAdj[i + 1] + dist(d[i], d[i + 1]);
    long best = prefix[n];
    for (int k = 0; k < n; k++) {
      int p = k > 0 ? d[k - 1] : 0;
      long cost = prefix[k] + dist(p, d[n - 1]) + suffixAdj[k];
      best = Math.min(best, cost);
    }
    return (int) best;
  }
}
